liveEl('live-form').onsubmit=e=>{e.preventDefault();if(liveEl('live-query').value.trim())loadResults();};for(const id of ['live-kind','live-provider'])liveEl(id).onchange=()=>{if(liveEl('live-query').value.trim())loadResults();};for(const id of ['live-year','live-genre','live-platform','live-owned','live-sort'])liveEl(id).onchange=drawResults;liveEl('live-reset').onclick=()=>{for(const id of ['live-kind','live-provider','live-year','live-genre','live-platform','live-owned'])liveEl(id).value='';liveEl('live-sort').value='relevance';if(liveQuery)loadResults();else drawResults();};liveEl('live-more').onclick=()=>loadResults(true);drawResults();

// Close only genuine backdrop clicks, including the original library status dialog.
for(const dialog of document.querySelectorAll('dialog')){
  let beganOutside=false;
  const outside=e=>{const r=dialog.getBoundingClientRect();return e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom);};
  dialog.addEventListener('pointerdown',e=>{beganOutside=outside(e);});
  dialog.addEventListener('click',e=>{if(beganOutside&&outside(e))dialog.close();beganOutside=false;});
}
liveEl('live-query').addEventListener('compositionstart',()=>{clearTimeout(liveTimer);searchController?.abort();++liveSeq;liveLoading=false;searchBusy(false);});
liveEl('live-query').addEventListener('input',e=>{
  if(e.isComposing)return;
  clearTimeout(liveTimer);searchController?.abort();++liveSeq;liveLoading=false;
  liveRecords=[];liveMore=false;liveFailure='';liveQuery=e.target.value.trim();liveLoading=liveQuery.length>=2;searchBusy(liveLoading);facets();drawResults();
  liveEl('live-providers').textContent='';
  liveEl('live-status').textContent=liveQuery.length<2?'Type at least 2 characters to search.':'Waiting for you to finish typing…';
  if(liveQuery.length>=2)liveTimer=setTimeout(()=>loadResults(),250);
});

// Keep the document fixed while any modal is open; preserve its exact scroll position.
let modalScroll=null,priorBodyStyle=null,priorRootOverflow='';
function syncModalScroll(){const open=!!document.querySelector('dialog[open]');if(open&&modalScroll===null){modalScroll=window.scrollY;priorBodyStyle={position:document.body.style.position,top:document.body.style.top,width:document.body.style.width,overflow:document.body.style.overflow};priorRootOverflow=document.documentElement.style.overflow;Object.assign(document.body.style,{position:'fixed',top:`-${modalScroll}px`,width:'100%',overflow:'hidden'});document.documentElement.style.overflow='hidden';}else if(!open&&modalScroll!==null){const y=modalScroll;Object.assign(document.body.style,priorBodyStyle);document.documentElement.style.overflow=priorRootOverflow;modalScroll=null;window.scrollTo({top:y,behavior:'instant'});}}
new MutationObserver(syncModalScroll).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});

