// Background refresh patches the latest saved entry, preserving other tabs' personal edits.
function persistMetadataSnapshot(entry){
 try{
  const latest=JSON.parse(localStorage.getItem('folio-library-v1'));
  if(!Array.isArray(latest))return false;
  const target=latest.find(x=>x.id===entry.id);
  if(!target?.metadata||!FolioIdentity.same(target.metadata,entry.metadata))return false;
  target.metadata=entry.metadata;target.sources=entry.sources;target.metadata_refreshed_at=entry.metadata_refreshed_at;
  localStorage.setItem('folio-library-v1',JSON.stringify(latest));Object.assign(entry,target);return true;
 }catch{return false;}
}

